    53→    def test_format_time_ago_seconds(self):
    54→        """Test format_time_ago with seconds."""
    55→        now = datetime.now(timezone.utc)
    56→        timestamp = (now - timedelta(seconds=30)).isoformat()
    57→        result = format_time_ago(timestamp)
    58→        self.assertIn("seconds ago", result)
    59→
    60→    def test_format_time_ago_minutes(self):
    61→        """Test format_time_ago with minutes."""
    62→        now = datetime.now(timezone.utc)
