   166→    def record_success(self, hook_cmd: str) -> Tuple[HookState, bool]:
   167→        """
   168→        Record a successful hook execution.
   169→
   170→        Updates consecutive success/failure counters and may transition
   171→        circuit breaker state from HALF_OPEN to CLOSED.
   172→
   173→        Args:
   174→            hook_cmd: The hook command string
   175→
   176→        Returns:
   177→            Tuple of (updated hook state, state_changed flag)
   178→            state_changed is True if circuit breaker transitioned to CLOSED
   179→        """
   180→        state = self._read_state()
   181→
   182→        if hook_cmd not in state.hooks:
   183→            state.hooks[hook_cmd] = HookState()
   184→
   185→        hook_state = state.hooks[hook_cmd]
   186→        hook_state.consecutive_successes += 1
   187→        hook_state.consecutive_failures = 0
   188→        hook_state.last_success = get_current_timestamp()
   189→
   190→        state_changed = False
   191→        if hook_state.state == CircuitState.HALF_OPEN.value:
   192→            # Check if we should close the circuit
   193→            # This would be configurable, but default to 2 successes
   194→            if hook_state.consecutive_successes >= 2:
   195→                hook_state.state = CircuitState.CLOSED.value
   196→                hook_state.failure_count = 0
   197→                hook_state.first_failure = None
   198→                hook_state.disabled_at = None
   199→                hook_state.retry_after = None
   200→                hook_state.last_error = None
   201→                state_changed = True
   202→
   203→        # Update global stats
   204→        state.global_stats.total_executions += 1
   205→        state.global_stats.last_updated = get_current_timestamp()
   206→        state.global_stats.hooks_disabled = sum(
   207→            1 for h in state.hooks.values() if h.state == CircuitState.OPEN.value
   208→        )
   209→
   210→        self._write_state(state)
   211→        return hook_state, state_changed
