   213→    def record_failure(
   214→        self,
   215→        hook_cmd: str,
   216→        error: str,
   217→        failure_threshold: int = 3
   218→    ) -> Tuple[HookState, bool]:
   219→        """
   220→        Record a failed hook execution.
   221→
   222→        Updates failure counters and may open circuit breaker if threshold exceeded.
   223→
   224→        Args:
   225→            hook_cmd: The hook command string
   226→            error: Error message from the failure
   227→            failure_threshold: Number of consecutive failures before opening circuit
   228→
   229→        Returns:
   230→            Tuple of (updated hook state, state_changed flag)
   231→            state_changed is True if circuit breaker transitioned to OPEN
   232→        """
   233→        state = self._read_state()
   234→
   235→        if hook_cmd not in state.hooks:
   236→            state.hooks[hook_cmd] = HookState()
   237→
   238→        hook_state = state.hooks[hook_cmd]
   239→        hook_state.consecutive_failures += 1
   240→        hook_state.consecutive_successes = 0
   241→        hook_state.failure_count += 1
   242→        hook_state.last_failure = get_current_timestamp()
   243→        hook_state.last_error = error
   244→
   245→        if hook_state.first_failure is None:
   246→            hook_state.first_failure = hook_state.last_failure
   247→
   248→        state_changed = False
   249→        if hook_state.consecutive_failures >= failure_threshold:
   250→            if hook_state.state != CircuitState.OPEN.value:
   251→                hook_state.state = CircuitState.OPEN.value
   252→                hook_state.disabled_at = get_current_timestamp()
   253→                # Calculate retry_after (5 minutes from now by default)
   254→                from datetime import datetime, timedelta, timezone
   255→                retry_time = datetime.now(timezone.utc) + timedelta(seconds=300)
   256→                hook_state.retry_after = retry_time.isoformat()
   257→                state_changed = True
   258→
   259→        # Update global stats
