   261→        state.global_stats.total_failures += 1
   262→        state.global_stats.last_updated = get_current_timestamp()
   263→        state.global_stats.hooks_disabled = sum(
   264→            1 for h in state.hooks.values() if h.state == CircuitState.OPEN.value
   265→        )
   266→
   267→        self._write_state(state)
   268→        return hook_state, state_changed
