   436→class TestConcurrentAccess:
   437→    """Test thread safety of concurrent operations."""
   438→
   439→    def test_concurrent_reads(self, state_manager):
   440→        """Test that concurrent reads don't interfere with each other."""
   441→        state_manager.record_failure("test_hook", "error")
   442→
   443→        results = []
   444→
   445→        def read_state():
   446→            state = state_manager.get_hook_state("test_hook")
   447→            results.append(state.failure_count)
   448→
   449→        threads = [threading.Thread(target=read_state) for _ in range(10)]
   450→        for t in threads:
   451→            t.start()
   452→        for t in threads:
   453→            t.join()
   454→
   455→        # All reads should see same value
   456→        assert all(count == 1 for count in results)
   457→
   458→    def test_concurrent_writes(self, state_manager):
   459→        """Test that concurrent writes are properly serialized."""
   460→        def record_failure():
   461→            state_manager.record_failure("test_hook", "error")
   462→
   463→        threads = [threading.Thread(target=record_failure) for _ in range(10)]
   464→        for t in threads:
   465→            t.start()
   466→        for t in threads:
   467→            t.join()
   468→
   469→        # Should have exactly 10 failures recorded
   470→        state = state_manager.get_hook_state("test_hook")
   471→        assert state.failure_count == 10
