   473→    def test_concurrent_mixed_operations(self, state_manager):
   474→        """Test concurrent mix of reads and writes."""
   475→        def worker(worker_id):
   476→            for i in range(5):
   477→                if worker_id % 2 == 0:
   478→                    state_manager.record_success(f"hook{worker_id}")
   479→                else:
   480→                    state_manager.record_failure(f"hook{worker_id}", "error")
