def _load_from_env(self) -> dict[str, Any]:
    """
    Load configuration from environment variables.

    Environment variable format:
        GUARDRAILS_CIRCUIT_BREAKER_ENABLED=true
        GUARDRAILS_CIRCUIT_BREAKER_FAILURE_THRESHOLD=5
        GUARDRAILS_LOGGING_LEVEL=DEBUG
        GUARDRAILS_STATE_FILE=/custom/path/state.json
    """
    config = {}

    for key, value in os.environ.items():
        if not key.startswith(self.ENV_PREFIX):
            continue

        # Remove prefix and convert to lowercase
        config_key = key[len(self.ENV_PREFIX):].lower()

        # Split into nested keys (e.g., "circuit_breaker_enabled" -> ["circuit_breaker", "enabled"])
        parts = config_key.split("_")

        # Build nested dictionary
        current = config
        for part in parts[:-1]:
            if part not in current:
                current[part] = {}
            current = current[part]

        # Set the value with type conversion
        final_key = parts[-1]
        current[final_key] = self._parse_env_value(value)

    return config

@staticmethod
def _parse_env_value(value: str) -> Any:
    """
    Parse environment variable value with type inference.

    Supports:
    - Boolean: true/false (case-insensitive)
    - Integer: numeric strings without decimal
    - String: everything else
    """
    # Boolean
    if value.lower() in ("true", "yes", "1", "on"):
        return True
    if value.lower() in ("false", "no", "0", "off"):
        return False

    # Integer
    if value.isdigit() or (value.startswith("-") and value[1:].isdigit()):
        return int(value)

    # String (default)
    return value

